<?php
namespace app\service;use think\facade\Db;
class AlipayService{
 public static function settings():array{$rows=Db::name('settings')->where('key','like','alipay.%')->select()->toArray();$s=[];foreach($rows as $x)$s[$x['key']]=$x['key']==='alipay.private_key'?SecretStore::decrypt((string)$x['value']):$x['value'];return$s;}
 private static function gateway(array $s):string{$u=parse_url(trim((string)($s['alipay.gateway']??'')));if(!$u||strtolower((string)($u['scheme']??''))!=='https'||isset($u['user'])||isset($u['pass'])||isset($u['port'])||!empty($u['query'])||!empty($u['fragment'])||strtolower((string)($u['host']??''))!=='openapi.alipay.com'||(string)($u['path']??'')!=='/gateway.do')throw new \RuntimeException('alipay_gateway_invalid');return'https://openapi.alipay.com/gateway.do';}
 private static function gatewayReady(array $s):bool{try{self::gateway($s);return true;}catch(\Throwable $e){return false;}}
 public static function ready():bool{$s=self::settings();return($s['alipay.enabled']??'0')==='1'&&!empty($s['alipay.app_id'])&&!empty($s['alipay.private_key'])&&!empty($s['alipay.public_key'])&&!empty($s['alipay.gateway'])&&!empty($s['alipay.notify_url'])&&self::gatewayReady($s);}
 private static function pem(string $key,string $kind):string{if(str_contains($key,'BEGIN'))return$key;$h=$kind==='private'?'PRIVATE KEY':'PUBLIC KEY';return"-----BEGIN $h-----\n".chunk_split(preg_replace('/\s+/','',$key),64,"\n")."-----END $h-----";}
 public static function sign(array $p,string $private):string{ksort($p);$a=[];foreach($p as $k=>$v)if($v!==''&&$v!==null&&$k!=='sign')$a[]=$k.'='.$v;if(!openssl_sign(implode('&',$a),$sig,self::pem($private,'private'),OPENSSL_ALGO_SHA256))throw new \RuntimeException('sign_failed');return base64_encode($sig);}
 public static function pagePayUrl(array $o):string{$s=self::settings();if(!self::ready())throw new \RuntimeException('alipay_not_ready');$biz=json_encode(['out_trade_no'=>$o['order_no'],'product_code'=>'FAST_INSTANT_TRADE_PAY','total_amount'=>self::centsToAmount((int)$o['amount_cents']),'subject'=>'LumenAPI 额度充值'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$p=['app_id'=>$s['alipay.app_id'],'method'=>'alipay.trade.page.pay','format'=>'JSON','charset'=>'utf-8','sign_type'=>'RSA2','timestamp'=>date('Y-m-d H:i:s'),'version'=>'1.0','notify_url'=>$s['alipay.notify_url'],'return_url'=>$s['alipay.return_url']??'','biz_content'=>$biz];$p['sign']=self::sign($p,$s['alipay.private_key']);return self::gateway($s).'?'.http_build_query($p,'','&',PHP_QUERY_RFC3986);}
 public static function centsToAmount(int $c):string{return intdiv($c,100).'.'.str_pad((string)($c%100),2,'0',STR_PAD_LEFT);}
 private static function api(string $method,array $biz,string $node):array{$s=self::settings();if(!self::ready())throw new \RuntimeException('alipay_not_ready');$p=['app_id'=>$s['alipay.app_id'],'method'=>$method,'format'=>'JSON','charset'=>'utf-8','sign_type'=>'RSA2','timestamp'=>date('Y-m-d H:i:s'),'version'=>'1.0','biz_content'=>json_encode($biz,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)];$p['sign']=self::sign($p,$s['alipay.private_key']);$ch=curl_init(self::gateway($s).'?'.http_build_query($p,'','&',PHP_QUERY_RFC3986));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]);$raw=curl_exec($ch);if($raw===false){$e=curl_error($ch);curl_close($ch);throw new \RuntimeException($e?:'alipay_api_failed');}$http=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($http!==200)throw new \RuntimeException('alipay_http_'.$http);$j=json_decode($raw,true);if(!is_array($j))throw new \RuntimeException('alipay_invalid_json');if(!self::verifyGatewayResponse($raw,$node))throw new \RuntimeException('alipay_signature_invalid');return$j;}
 public static function refund(string $orderNo,int $amountCents,string $refundNo,string $reason='LumenAPI 管理员退款'):array{return self::api('alipay.trade.refund',['out_trade_no'=>$orderNo,'refund_amount'=>self::centsToAmount($amountCents),'out_request_no'=>$refundNo,'refund_reason'=>$reason],'alipay_trade_refund_response');}
 public static function refundQuery(string $orderNo,string $refundNo):array{return self::api('alipay.trade.fastpay.refund.query',['out_trade_no'=>$orderNo,'out_request_no'=>$refundNo],'alipay_trade_fastpay_refund_query_response');}
 public static function query(string $no):array{$s=self::settings();if(!self::ready())throw new \RuntimeException('alipay_not_ready');$p=['app_id'=>$s['alipay.app_id'],'method'=>'alipay.trade.query','format'=>'JSON','charset'=>'utf-8','sign_type'=>'RSA2','timestamp'=>date('Y-m-d H:i:s'),'version'=>'1.0','biz_content'=>json_encode(['out_trade_no'=>$no],JSON_UNESCAPED_SLASHES)];$p['sign']=self::sign($p,$s['alipay.private_key']);$ch=curl_init(self::gateway($s).'?'.http_build_query($p,'','&',PHP_QUERY_RFC3986));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>15,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]);$raw=curl_exec($ch);if($raw===false){$e=curl_error($ch);curl_close($ch);throw new \RuntimeException($e?:'query_failed');}$http=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($http!==200)throw new \RuntimeException('query_http_'.$http);$j=json_decode($raw,true);if(!is_array($j))throw new \RuntimeException('query_invalid_json');if(!self::verifyGatewayResponse($raw,'alipay_trade_query_response'))throw new \RuntimeException('query_signature_invalid');return$j;}
 private static function node(string $raw,string $name):?string{$pos=strpos($raw,'"'.$name.'"');if($pos===false)return null;$i=strpos($raw,':',$pos);if($i===false)return null;$i++;$n=strlen($raw);while($i<$n&&ctype_space($raw[$i]))$i++;if($i>=$n||$raw[$i]!=='{')return null;$start=$i;$d=0;$str=false;$esc=false;for(;$i<$n;$i++){$c=$raw[$i];if($str){if($esc){$esc=false;continue;}if($c==='\\'){$esc=true;continue;}if($c==='"')$str=false;continue;}if($c==='"'){$str=true;continue;}if($c==='{')$d++;elseif($c==='}'&&--$d===0)return substr($raw,$start,$i-$start+1);}return null;}
 public static function verifyGatewayResponse(string $raw,string $name):bool{$j=json_decode($raw,true);$sign=is_array($j)?(string)($j['sign']??''):'';$body=self::node($raw,$name);$sig=base64_decode($sign,true);if($sign===''||$body===null||$sig===false)return false;$s=self::settings();return openssl_verify($body,$sig,self::pem((string)($s['alipay.public_key']??''),'public'),OPENSSL_ALGO_SHA256)===1;}
 public static function verifyNotify(array $p):bool{$s=self::settings();$sign=(string)($p['sign']??'');unset($p['sign'],$p['sign_type']);ksort($p);$a=[];foreach($p as $k=>$v)if($v!==''&&$v!==null)$a[]=$k.'='.$v;$sig=base64_decode($sign,true);return $sig!==false&&openssl_verify(implode('&',$a),$sig,self::pem((string)($s['alipay.public_key']??''),'public'),OPENSSL_ALGO_SHA256)===1;}
}

